import React, { useEffect, useRef, useState } from "react";
import axios from "axios";
import Banner from "./Banner";
import toast, { Toaster } from "react-hot-toast";
import '../styles/main.css';

export default function Admissions() {
  const formRef = useRef(null);
  const onlineRef = useRef(null);
  const feeRef = useRef(null);

  const [admissionContent, setAdmissionContent] = useState({});
  const [feeStructure, setFeeStructure] = useState(null);

  useEffect(() => {
    // fetch admission page content
    const fetchContent = async () => {
      try {
        const res = await axios.get("http://localhost:5000/api/admissionsContent");
        if(res.data.success) setAdmissionContent(res.data.data);
      } catch(err) {
        console.error(err);
        toast.error("Failed to load admission content");
      }
    };

    // fetch fee structure
    const fetchFee = async () => {
      try {
        const res = await axios.get("http://localhost:5000/api/fees");
        if(res.data.success) setFeeStructure(res.data.data);
      } catch(err) {
        console.error(err);
        toast.error("Failed to load fee structure");
      }
    };

    fetchContent();
    fetchFee();
  }, []);

  const scrollToSection = (ref) => ref.current.scrollIntoView({ behavior: "smooth" });

  return (
    <>
      <Toaster />
      <Banner />
      <div className="admissions-page">
        <div className="left-column">
          <h2>Admissions</h2>
          <div className="info-box">
            <p onClick={() => scrollToSection(formRef)}>Application Form</p>
            <p onClick={() => scrollToSection(onlineRef)}>Apply Online</p>
            <p onClick={() => scrollToSection(feeRef)}>Fee Structure</p>
          </div>
        </div>

        <div className="right-column">
          <div ref={formRef}>
            <h2>Application Form</h2>
            <div dangerouslySetInnerHTML={{ __html: admissionContent?.applicationForm }} />
          </div>

          <div ref={onlineRef} style={{ marginTop: "50px" }}>
            <h2>Apply Online</h2>
            <div dangerouslySetInnerHTML={{ __html: admissionContent?.applyOnline }} />
            <button className="apply-btn" onClick={() => window.open("/admission-form", "_blank")}>
              Apply Now
            </button>
          </div>

          <div ref={feeRef} style={{ marginTop: "50px" }}>
            <h2>Fee Structure ({feeStructure?.academicYear || "2025-26"})</h2>
            <div dangerouslySetInnerHTML={{ __html: admissionContent?.feeStructure }} />
            {feeStructure?.items && (
              <table className="fee-table">
                <thead>
                  <tr><th>Particular</th><th>Amount (₹)</th></tr>
                </thead>
                <tbody>
                  {feeStructure.items.map(i => (
                    <tr key={i.key}><td>{i.title}</td><td>₹{i.amount}</td></tr>
                  ))}
                  <tr className="fee-total">
                    <td><b>Total</b></td>
                    <td><b>₹{feeStructure.items.reduce((s, i) => s + i.amount, 0)}</b></td>
                  </tr>
                </tbody>
              </table>
            )}
          </div>
        </div>
      </div>
    </>
  );
}
